//! Unicode Normalization Forms (UAX #15) for String.prototype.normalize (§22.1.3.15) and
//! canonical equivalence in localeCompare (§22.1.3.12). Tables: normalization_tables.rs,
//! generated by gen_unicode_norm.py. Strings are code units: lone surrogates are code points
//! with canonical combining class 0 and no decomposition, so they pass through unchanged.
use super::normalization_tables::{
    CANONICAL, CANONICAL_DATA, CCC, COMPATIBILITY, COMPATIBILITY_DATA, COMPOSE,
};

#[derive(Clone, Copy, PartialEq)]
pub(super) enum Form {
    Nfc,
    Nfd,
    Nfkc,
    Nfkd,
}

// Hangul syllable composition constants (Unicode §3.12).
const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn ccc(cp: u32) -> u8 {
    match CCC.binary_search_by(|&(a, b, _)| {
        if b < cp {
            std::cmp::Ordering::Less
        } else if a > cp {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(i) => CCC[i].2,
        Err(_) => 0,
    }
}

fn lookup(table: &[(u32, u16, u8)], data: &'static [u32], cp: u32) -> Option<&'static [u32]> {
    let i = table.binary_search_by_key(&cp, |&(c, _, _)| c).ok()?;
    let (_, start, len) = table[i];
    Some(&data[start as usize..start as usize + len as usize])
}

/// Full decomposition of one code point (canonical, or compatibility when `compat`).
fn decompose_into(cp: u32, compat: bool, out: &mut Vec<u32>) {
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        out.push(L_BASE + s / N_COUNT);
        out.push(V_BASE + (s % N_COUNT) / T_COUNT);
        if s % T_COUNT != 0 {
            out.push(T_BASE + s % T_COUNT);
        }
        return;
    }
    let mapped = if compat {
        lookup(COMPATIBILITY, COMPATIBILITY_DATA, cp)
            .or_else(|| lookup(CANONICAL, CANONICAL_DATA, cp))
    } else {
        lookup(CANONICAL, CANONICAL_DATA, cp)
    };
    match mapped {
        Some(d) => out.extend_from_slice(d),
        None => out.push(cp),
    }
}

fn compose_pair(a: u32, b: u32) -> Option<u32> {
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a)
        && (a - S_BASE) % T_COUNT == 0
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
    {
        return Some(a + (b - T_BASE));
    }
    COMPOSE
        .binary_search_by_key(&(a, b), |&(x, y, _)| (x, y))
        .ok()
        .map(|i| COMPOSE[i].2)
}

fn code_points(units: &[u16]) -> Vec<u32> {
    char::decode_utf16(units.iter().copied())
        .map(|r| r.map_or_else(|e| e.unpaired_surrogate() as u32, |c| c as u32))
        .collect()
}

/// UAX #15 §3: decomposition, the Canonical Ordering Algorithm, then (NFC/NFKC) the
/// Canonical Composition Algorithm.
pub(super) fn normalize(units: &[u16], form: Form) -> Vec<u16> {
    // Fast path: ASCII is invariant under every form.
    if units.iter().all(|&u| u < 0x80) {
        return units.to_vec();
    }
    let compat = matches!(form, Form::Nfkc | Form::Nfkd);
    let mut cps = Vec::with_capacity(units.len());
    for cp in code_points(units) {
        decompose_into(cp, compat, &mut cps);
    }
    // Canonical Ordering: stable sort of each run of non-starters by combining class.
    let mut i = 0;
    while i < cps.len() {
        if ccc(cps[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < cps.len() && ccc(cps[i]) != 0 {
            i += 1;
        }
        cps[start..i].sort_by_key(|&cp| ccc(cp));
    }
    if matches!(form, Form::Nfc | Form::Nfkc) {
        cps = compose(cps);
    }
    let mut out = Vec::with_capacity(cps.len());
    for cp in cps {
        match char::from_u32(cp) {
            Some(c) => {
                let mut buf = [0u16; 2];
                out.extend_from_slice(c.encode_utf16(&mut buf));
            }
            None => out.push(cp as u16),
        }
    }
    out
}

/// Canonical Composition Algorithm (UAX #15 §3.11 / Unicode §3.11 D117).
fn compose(cps: Vec<u32>) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::with_capacity(cps.len());
    // Index in `out` of the last starter, and the largest ccc seen since it (or 0 when
    // the previous character was the starter itself).
    let mut starter: Option<usize> = None;
    let mut last_ccc: i32 = -1;
    for cp in cps {
        let class = ccc(cp) as i32;
        if let Some(s) = starter {
            // C is not blocked from the starter when the previous char has a lower ccc
            // (non-zero), or the previous char is the starter itself.
            let unblocked = last_ccc == -1 || (last_ccc != 0 && last_ccc < class);
            if unblocked {
                if let Some(composite) = compose_pair(out[s], cp) {
                    out[s] = composite;
                    continue;
                }
            }
        }
        if class == 0 {
            starter = Some(out.len());
            last_ccc = -1;
        } else {
            last_ccc = class;
        }
        out.push(cp);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    /// UAX #15 conformance: set NORMALIZATION_TEST to a NormalizationTest.txt of the same
    /// Unicode version as the tables (the file is not vendored; the test skips without it).
    #[test]
    fn normalization_test_file() {
        let Ok(path) = std::env::var("NORMALIZATION_TEST") else {
            return;
        };
        let text = std::fs::read_to_string(path).unwrap();
        let utf16 = |field: &str| -> Vec<u16> {
            let s: String = field
                .split_whitespace()
                .map(|h| char::from_u32(u32::from_str_radix(h, 16).unwrap()).unwrap())
                .collect();
            s.encode_utf16().collect()
        };
        let (mut cases, mut failures) = (0, vec![]);
        for line in text.lines() {
            if line.starts_with('#') || line.starts_with('@') || line.trim().is_empty() {
                continue;
            }
            let c: Vec<Vec<u16>> = line.split(';').take(5).map(utf16).collect();
            let checks = [
                (Form::Nfc, &c[0], &c[1]),
                (Form::Nfc, &c[1], &c[1]),
                (Form::Nfc, &c[2], &c[1]),
                (Form::Nfc, &c[3], &c[3]),
                (Form::Nfc, &c[4], &c[3]),
                (Form::Nfd, &c[0], &c[2]),
                (Form::Nfd, &c[1], &c[2]),
                (Form::Nfd, &c[2], &c[2]),
                (Form::Nfd, &c[3], &c[4]),
                (Form::Nfd, &c[4], &c[4]),
                (Form::Nfkc, &c[0], &c[3]),
                (Form::Nfkc, &c[2], &c[3]),
                (Form::Nfkc, &c[4], &c[3]),
                (Form::Nfkd, &c[0], &c[4]),
                (Form::Nfkd, &c[2], &c[4]),
                (Form::Nfkd, &c[3], &c[4]),
            ];
            cases += 1;
            if checks
                .iter()
                .any(|(f, input, want)| normalize(input, *f) != **want)
            {
                failures.push(line.to_string());
            }
        }
        assert!(
            failures.is_empty(),
            "{} of {cases} lines fail, first: {:?}",
            failures.len(),
            &failures[..failures.len().min(5)]
        );
    }
    #[test]
    fn lone_surrogates_pass_through() {
        let s = [0x61, 0xD800, 0x301, 0xDC00];
        assert_eq!(normalize(&s, Form::Nfc), vec![0x61, 0xD800, 0x301, 0xDC00]);
        assert_eq!(normalize(&[0x41, 0x30A], Form::Nfc), vec![0xC5]);
    }
}
